arguments.command:
cd /app; python3 - <<'E'
import csv,collections
for f in ['sites','collectors','taxa','specimens']:
    b=open(f'seeds/{f}.csv','rb').read()
    try: b.decode('utf-8');print(f,'utf8 ok')
    except Exception as e: print(f,'not utf8',e)
    print(f, b[:3], b.count(b'\r\n'), b.count(b'\r'))
    try: b.decode('cp1252')
    except Exception as e: print(' cp1252 fail',e)
rows=list(csv.DictReader(open('seeds/specimens.csv',encoding='latin-1')))
print(collections.Counter(r['basis'] for r in rows))
print(collections.Counter(r['date'][:0]+str(len(r['date'])) for r in rows))
print([r['elevation_m'] for r in rows if not r['elevation_m'].lstrip('-').isdigit()][:20])
E
grep -c . seeds/*.csv; grep -P '[\x00-\x1f]' -c seeds/*.csv; cat seeds/sites.csv | head -30

